css:
.container {
  width: 100%;
  background-position: center center;
  height: 100%;
  background:
    conic-gradient(
        from 0deg at 68.4% 85.35%,
        #fff0 0 60deg,
        #38bba7 0 120deg,
        #159380 0 202.5deg,
        #fff0 0 360deg
      )
      50%/20vmin 25vmin,
    conic-gradient(
        from 0deg at 31.6% 85.35%,
        #fff0 0 157.5deg,
        #17a18c 0 240deg,
        #38bba7 0 300deg,
        #fff0 0 360deg
      )
      50%/20vmin 25vmin,
    conic-gradient(
        from 0deg at 81.35% 35.5%,
        #fff0 0 22.75deg,
        #128070 0 157.25deg,
        #fff0 0 360deg
      )
      50%/20vmin 25vmin,
    conic-gradient(
        from 0deg at 18.65% 35.5%,
        #fff0 0 202.75deg,
        #01685b 0 337.25deg,
        #fff0 0 360deg
      )
      50%/20vmin 25vmin,
    conic-gradient(
        from 0deg at 50% 50%,
        #fff0 0 60deg,
        #17a18c 0 157.5deg,
        #01685b 0 180.1deg,
        #128070 0 202.5deg,
        #159380 0 300deg,
        #fff0 0 360deg
      )
      50%/20vmin 25vmin,
    conic-gradient(
        from 0deg at 50% 21.15%,
        #fff0 0 22.5deg,
        #159380 0 120deg,
        #38bba7 0 240deg,
        #17a18c 0 337.5deg,
        #fff0 0 360deg
      )
      50%/20vmin 25vmin,
    linear-gradient(90deg, #128070 0 50%, #01685b 0 100%) 50%/20vmin 25vmin;
}
